# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İMANIN MAHİYETİ, ÇEŞİTLERİ VE İNSAN HAYATINDAKİ YERİ (TDB.9.2.2)</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">TASDİK, İKRAR VE KAPSAM</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• Tasdik: Kalp ile onaylama (asıl)</text>\n  <text x="32" y="112" font-size="10.5" fill="#1e3a8a">• İkrar: Dil ile söyleme</text>\n  <text x="32" y="136" font-size="10.5" font-weight="bold" fill="#1d4ed8">• İcmâlî İman: Toptan ve özet</text>\n  <text x="32" y="154" font-size="10.5" fill="#1e3a8a">  inanma (Kelime-i Tevhid)</text>\n  <text x="32" y="178" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Tafsîlî İman: Altı iman esasına</text>\n  <text x="32" y="196" font-size="10.5" fill="#1e3a8a">  ayrı ayrı ve ayrıntılı inanma</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">TAKLİDÎ VE TAHKİKÎ İMAN</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• Taklidî İman: Delillere</text>\n  <text x="257" y="110" font-size="10.5" fill="#14532d">  dayanmadan çevreden görerek</text>\n  <text x="257" y="128" font-size="10.5" fill="#14532d">  ve taklit ederek inanma</text>\n  <text x="257" y="154" font-size="10.5" font-weight="bold" fill="#15803d">• Tahkikî İman: Araştırma,</text>\n  <text x="257" y="172" font-size="10.5" font-weight="bold" fill="#15803d">  tefekkür ve delillerle</text>\n  <text x="257" y="190" font-size="10.5" fill="#14532d">  ulaşılan bilinçli, sağlam iman</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">İMANIN İNSANA KATKILARI</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• Yaratılış gayesini kavratır</text>\n  <text x="482" y="114" font-size="10.5" fill="#78350f">• Kalbe huzur ve güven verir</text>\n  <text x="482" y="132" font-size="10.5" fill="#78350f">  (Ra\'d suresi, 28. ayet)</text>\n  <text x="482" y="154" font-size="10.5" font-weight="bold" fill="#b45309">• Sabır, ümit ve tevekkül gücü</text>\n  <text x="482" y="176" font-size="10.5" fill="#78350f">• Kula kulluktan kurtararak</text>\n  <text x="482" y="194" font-size="10.5" fill="#78350f">  gerçek özgürlüğe ulaştırır</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İMAN - SALİH AMEL - GÜZEL AHLAK BÜTÜNLÜĞÜ</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">İMAN VE SALİH AMEL İLİŞKİSİ</text>\n  <text x="34" y="94" font-size="10.5" fill="#14532d">• İman kalpte kök salan bir ağaca, salih amel</text>\n  <text x="34" y="112" font-size="10.5" fill="#14532d">  ise o ağacın dallarına ve meyvelerine benzer</text>\n  <text x="34" y="136" font-size="10.5" font-weight="bold" fill="#15803d">• Ehl-i Sünnet İlkesi: Amel imandan bir cüz</text>\n  <text x="34" y="154" font-size="10.5" fill="#14532d">  (parça) değildir; günah işleyen mümin dinden</text>\n  <text x="34" y="172" font-size="10.5" fill="#14532d">  çıkmaz ancak salih amel imanı korur ve besler</text>\n  <text x="34" y="196" font-size="10.5" font-weight="bold" fill="#15803d">• Asr suresi: İman + Salih Amel + Hakkı/Sabrı tavsiye</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">İHSAN, TAKVA VE AHLAKİ ERDEMLER</text>\n  <text x="374" y="94" font-size="10.5" font-weight="bold" fill="#7e22ce">• İhsan: Allah\'ı görüyormuş gibi kulluk etmek</text>\n  <text x="374" y="112" font-size="10.5" fill="#581c87">  (O\'nu görmesek de O\'nun bizi gördüğü bilinci)</text>\n  <text x="374" y="136" font-size="10.5" font-weight="bold" fill="#7e22ce">• Takva: Allah\'ın sevgisini kaybetmekten</text>\n  <text x="374" y="154" font-size="10.5" fill="#581c87">  sakınarak emirlerine uyup günahlardan kaçınma</text>\n  <text x="374" y="178" font-size="10.5" fill="#581c87">• Ahlaki Meyveler: Doğruluk (sıdk), emanet,</text>\n  <text x="374" y="196" font-size="10.5" fill="#581c87">  adalet, merhamet ve kul hakkına riayet</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YÂSÎN SURESİ (77 - 83. AYETLER) İMAN VE YARATILIŞ DELİLLERİ</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">İLK YARATILIŞ DELİLİ (77-79)</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• İnsanın bir damla sudan (nutfe)</text>\n  <text x="32" y="110" font-size="10.5" fill="#1e3a8a">  yaratıldığının hatırlatılması</text>\n  <text x="32" y="134" font-size="10.5" fill="#1e3a8a">• \'Çürümüş kemikleri kim</text>\n  <text x="32" y="152" font-size="10.5" fill="#1e3a8a">  diriltecek?\' sorusuna cevap:</text>\n  <text x="32" y="176" font-size="10.5" font-weight="bold" fill="#1d4ed8">• \'Onları ilk defa yaratan</text>\n  <text x="32" y="194" font-size="10.5" font-weight="bold" fill="#1d4ed8">  diriltecektir!\' (Ba\'s delili)</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">KEVNÎ KUDRET DELİLİ (80-81)</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• Yemyeşil ağaçtan ateş çıkaran</text>\n  <text x="257" y="110" font-size="10.5" fill="#14532d">  ilahi kudret (zıtların uyumu)</text>\n  <text x="257" y="134" font-size="10.5" fill="#14532d">• Gökleri ve yeri yaratan Allah</text>\n  <text x="257" y="152" font-size="10.5" fill="#14532d">  insanları yeniden yaratmaya</text>\n  <text x="257" y="170" font-size="10.5" fill="#14532d">  elbette kadirdir</text>\n  <text x="257" y="194" font-size="10.5" font-weight="bold" fill="#15803d">• Hallâk (Yaratan) ve Alîm (Bilen)</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">KÜN FE YEKÛN &amp; MELEKÛT (82-83)</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• Bir şeyi dilediğinde O\'nun emri</text>\n  <text x="482" y="110" font-size="10.5" font-weight="bold" fill="#b45309">  \'Ol!\' (Kün) demektir; o da</text>\n  <text x="482" y="128" font-size="10.5" font-weight="bold" fill="#b45309">  hemen oluverir (fe yekûn)</text>\n  <text x="482" y="154" font-size="10.5" fill="#78350f">• Her şeyin mülkü ve hükümranlığı</text>\n  <text x="482" y="172" font-size="10.5" fill="#78350f">  (Melekût) Allah\'ın elindedir</text>\n  <text x="482" y="194" font-size="10.5" font-weight="bold" fill="#b45309">• Dönüş Allah\'adır (İleyhi türceûn)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
